patch:
diff --git a/repro/no-useless-assignment-try-catch.test.js b/repro/no-useless-assignment-try-catch.test.js
new file mode 100644
index 0000000..3fa763b
--- /dev/null
+++ b/repro/no-useless-assignment-try-catch.test.js
@@ -0,0 +1,45 @@
+"use strict";
+
+// Reproduction for: no-useless-assignment false positive in try-catch block.
+// Run: npx mocha repro/no-useless-assignment-try-catch.test.js
+
+const rule = require("../lib/rules/no-useless-assignment");
+const RuleTester = require("../lib/rule-tester/rule-tester");
+
+const ruleTester = new RuleTester({
+    languageOptions: { ecmaVersion: "latest", sourceType: "module" }
+});
+
+ruleTester.run("no-useless-assignment (issue repro)", rule, {
+    valid: [
+
+        // Reporter's exact snippet: value assigned in try is read in catch
+        // if unsafeFn() throws, so the assignment is not useless.
+        `async function fn() {
+          let intermediaryValue;
+          try {
+            intermediaryValue = 42;
+            unsafeFn();
+            return { error: undefined };
+          } catch {
+            return { intermediaryValue };
+          }
+        }
+
+        function unsafeFn() {
+          throw new Error();
+        }`,
+
+        // Control (passes): same code without the `return` in the try block.
+        `async function fn() {
+          let intermediaryValue;
+          try {
+            intermediaryValue = 42;
+            unsafeFn();
+          } catch {
+            return { intermediaryValue };
+          }
+        }`
+    ],
+    invalid: []
+});
